# WRF Total Rainfall Classifications (mm)
# Styled to match ICPAC Weather Info map legend:
# grey -> orange -> yellow -> green ramp

CLASS
    NAME "0-1 mm"
    EXPRESSION ([rainfall_mm] > 0 AND [rainfall_mm] <= 1)
    STYLE
        COLOR 217 217 217
        OUTLINECOLOR 217 217 217
    END
END

CLASS
    NAME "1-10 mm"
    EXPRESSION ([rainfall_mm] > 1 AND [rainfall_mm] <= 10)
    STYLE
        COLOR 255 176 0
        OUTLINECOLOR 255 176 0
    END
END

CLASS
    NAME "10-30 mm"
    EXPRESSION ([rainfall_mm] > 10 AND [rainfall_mm] <= 30)
    STYLE
        COLOR 255 242 51
        OUTLINECOLOR 255 242 51
    END
END

CLASS
    NAME "30-50 mm"
    EXPRESSION ([rainfall_mm] > 30 AND [rainfall_mm] <= 50)
    STYLE
        COLOR 157 255 88
        OUTLINECOLOR 157 255 88
    END
END

CLASS
    NAME "50-100 mm"
    EXPRESSION ([rainfall_mm] > 50 AND [rainfall_mm] <= 100)
    STYLE
        COLOR 50 230 70
        OUTLINECOLOR 50 230 70
    END
END

CLASS
    NAME "100-200 mm"
    EXPRESSION ([rainfall_mm] > 100 AND [rainfall_mm] <= 200)
    STYLE
        COLOR 27 157 55
        OUTLINECOLOR 27 157 55
    END
END

CLASS
    NAME ">200 mm"
    EXPRESSION ([rainfall_mm] > 200)
    STYLE
        COLOR 27 157 55
        OUTLINECOLOR 27 157 55
    END
END
